class ClientOverrides {
  static apply(config) {
    for (const [key, data] of Object.entries(CLIENT_OVERRIDES_CONFIG)) {
      const enabledSetting = game.settings.get(
        MODULE_ID,
        `user-${key}-enabled`
      );
      if (enabledSetting === false) {
        foundry.utils.setProperty(config, `${data.path}.enabled`, false);
        continue;
      }

      if (data.intensitySubPath) {
        const intensitySetting = game.settings.get(
          MODULE_ID,
          `user-${key}-intensity`
        );
        if (intensitySetting !== 100) {
          const fullIntensityPath = `${data.path}.${data.intensitySubPath}`;
          const originalValue = foundry.utils.getProperty(
            config,
            fullIntensityPath
          );
          if (typeof originalValue === "number") {
            const newValue = originalValue * (intensitySetting / 100);
            foundry.utils.setProperty(config, fullIntensityPath, newValue);
          }
        }
      }
    }

    // New global accessibility overrides
    const disableDistortion = game.settings.get(
      MODULE_ID,
      "user-disable-distortion"
    );
    if (disableDistortion) {
      if (config.heatDistortion) config.heatDistortion.enabled = false;
      if (config.postProcessing?.lensDistortion)
        config.postProcessing.lensDistortion.enabled = false;
    }

    const disableFringe = game.settings.get(
      MODULE_ID,
      "user-disable-color-fringe"
    );
    if (disableFringe) {
      if (config.baseShine?.rgbSplit) config.baseShine.rgbSplit.enabled = false;
      if (config.postProcessing?.chromaticAberration)
        config.postProcessing.chromaticAberration.enabled = false;
    }

    return config;
  }
}

class CurveEditor {
  constructor(container, options = {}) {
    this.container = container;
    this.width = options.width || 256;
    this.height = options.height || 256;
    this.onChange = options.onChange || (() => {});

    // Use a standard "Y-up" coordinate system internally, where y=0 is the bottom.
    this.points = [
      {
        x: 0,
        y: 0,
      },
      {
        x: this.width * 0.25,
        y: this.height * 0.25,
      },
      {
        x: this.width * 0.75,
        y: this.height * 0.75,
      },
      {
        x: this.width,
        y: this.height,
      },
    ];

    this.activePoint = null;
    this.init();
  }

  init() {
    this.svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    this.svg.setAttribute("width", this.width);
    this.svg.setAttribute("height", this.height);
    this.svg.setAttribute("viewBox", `0 0 ${this.width} ${this.height}`);
    this.container.appendChild(this.svg);

    // Create a group for the grid
    const gridGroup = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "g"
    );
    gridGroup.setAttribute("stroke", "rgba(255, 255, 255, 0.2)");
    gridGroup.setAttribute("stroke-width", "0.5");
    this.svg.appendChild(gridGroup);

    // Add grid lines (e.g., every 25%)
    for (let i = 1; i < 4; i++) {
      const pos = this.width * (i / 4);
      // Vertical line
      const vLine = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "line"
      );

      vLine.setAttribute("x1", pos);

      vLine.setAttribute("y1", 0);

      vLine.setAttribute("x2", pos);
      vLine.setAttribute("y2", this.height);
      gridGroup.appendChild(vLine);
      // Horizontal line
      const hLine = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "line"
      );

      hLine.setAttribute("x1", 0);

      hLine.setAttribute("y1", pos);
      hLine.setAttribute("x2", this.width);

      hLine.setAttribute("y2", pos);
      gridGroup.appendChild(hLine);
    }

    // Add the neutral 1:1 diagonal line
    const neutralLine = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "line"
    );

    neutralLine.setAttribute("x1", 0);
    neutralLine.setAttribute("y1", this.height);
    neutralLine.setAttribute("x2", this.width);

    neutralLine.setAttribute("y2", 0);
    neutralLine.setAttribute("stroke", "rgba(255,255,255,0.2)");
    neutralLine.setAttribute("stroke-width", "1");
    neutralLine.setAttribute("stroke-dasharray", "4 4");
    this.svg.appendChild(neutralLine);

    this.path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    this.path.setAttribute("fill", "none");
    this.path.setAttribute("stroke", "#00aaff");
    this.path.setAttribute("stroke-width", "2.5"); // Thicker path
    this.svg.appendChild(this.path);

    this.controlPoints = this.points.map((p, i) => {
      // When drawing, we flip the y-coordinate to match SVG's "y-down" system.
      const circle = document.createElementNS(
        "http://www.w3.org/2000/svg",
        "circle"
      );
      circle.setAttribute("cx", p.x);

      circle.setAttribute("cy", this.height - p.y);

      circle.setAttribute("r", 6);
      circle.setAttribute("fill", "rgba(0, 170, 255, 0.5)"); // Semi-transparent fill
      circle.setAttribute("stroke", "#fff"); // White stroke
      circle.setAttribute("stroke-width", "2");
      circle.setAttribute("cursor", "grab");
      this.svg.appendChild(circle);

      circle.addEventListener("mousedown", (_e) => {
        this.activePoint = i;
      });
      return circle;
    });

    this.svg.addEventListener("mousemove", this.onDrag.bind(this));
    this.svg.addEventListener("mouseup", this.onEndDrag.bind(this));
    this.svg.addEventListener("mouseleave", this.onEndDrag.bind(this));

    this.drawCurve();
  }

  onDrag(e) {
    if (this.activePoint === null) return;
    e.preventDefault();
    this.svg.style.cursor = "grabbing";

    const rect = this.svg.getBoundingClientRect();
    let x = e.clientX - rect.left;
    let y = e.clientY - rect.top;

    // Clamp screen coordinates
    x = Math.max(0, Math.min(this.width, x));
    y = Math.max(0, Math.min(this.height, y));

    // First and last points are fixed horizontally
    if (this.activePoint > 0 && this.activePoint < this.points.length - 1) {
      this.points[this.activePoint].x = x;
    }
    // Convert the SVG's "y-down" coordinate back to our internal "y-up" system for storage.
    this.points[this.activePoint].y = this.height - y;

    this.drawCurve();
  }

  onEndDrag() {
    if (this.activePoint !== null) {
      this.svg.style.cursor = "default";
      this.activePoint = null;
      this.onChange(this.getNormalizedPoints());
    }
  }

  setPoints(normalizedPoints) {
    if (!normalizedPoints || normalizedPoints.length !== 4) {
      console.warn("CurveEditor: Invalid points data provided for setPoints.");
      return;
    }

    // Directly map normalized "y-up" data to internal "y-up" system.
    this.points = normalizedPoints.map((p) => ({
      x: p.x * this.width,
      y: p.y * this.height,
    }));

    this.drawCurve();
    // Trigger the LUT update by calling the onChange callback
    this.onChange(this.getNormalizedPoints(), {
      isLoading: true,
    });
  }

  getNormalizedPoints() {
    // Directly normalize the internal "y-up" points.
    return this.points.map((p) => ({
      x: p.x / this.width,
      y: p.y / this.height,
    }));
  }

  drawCurve() {
    this.controlPoints.forEach((circle, i) => {
      // When drawing, flip the internal "y-up" coordinate to SVG's "y-down" screen coordinate.
      circle.setAttribute("cx", this.points[i].x);

      circle.setAttribute("cy", this.height - this.points[i].y);
    });

    const p = this.points;
    // The path data must also be flipped for rendering in the y-down SVG canvas.
    const pathData = `M ${p[0].x},${this.height - p[0].y} C ${p[1].x},${
      this.height - p[1].y
    } ${p[2].x},${this.height - p[2].y} ${p[3].x},${this.height - p[3].y}`;
    this.path.setAttribute("d", pathData);
  }
}



/**
 * Generates separate color and alpha lists for the particle emitter from a single gradient array.
 * @param {Array<object>} gradient - An array of stop objects, each with {time, color, alpha}.
 * @returns {{isColorStatic: boolean, staticColor?: string, colorList?: object, isAlphaStatic: boolean, staticAlpha?: number, alphaList?: object}} An object containing the config lists or static values for the behaviors.
 */
function _generateBehaviorListsFromGradient(gradient) {
  if (!gradient || gradient.length === 0) {
    return {
      isColorStatic: true,
      staticColor: "#ffffff",
      isAlphaStatic: true,
      staticAlpha: 1.0,
    };
  }

  const sortedGradient = [...gradient].sort((a, b) => a.time - b.time);

  const firstColor = sortedGradient[0].color;
  const allColorsSame = sortedGradient.every(
    (stop) => stop.color === firstColor
  );

  const firstAlpha = sortedGradient[0].alpha;
  const allAlphasSame = sortedGradient.every(
    (stop) => Math.abs(stop.alpha - firstAlpha) < 0.001
  );

  const result = {
    isColorStatic: allColorsSame,
    isAlphaStatic: allAlphasSame,
  };

  if (allColorsSame) {
    result.staticColor = firstColor;
  } else {
    result.colorList = {
      list: sortedGradient.map((s) => ({ value: s.color, time: s.time })),
    };
  }

  if (allAlphasSame) {
    result.staticAlpha = firstAlpha;
  } else {
    result.alphaList = {
      list: sortedGradient.map((s) => ({ value: s.alpha, time: s.time })),
    };
  }

  return result;
}

/**
 * Generates a brightness list for a particle behavior from a gradient array.
 * @param {Array<object>} gradient - An array of stop objects, each with {time, color, alpha}.
 * @returns {object} A config list for a value-based behavior.
 */
function _generateEmissiveListFromGradient(gradient) {
  if (!gradient || gradient.length < 1) {
    // Fallback to a single node list representing no emission.
    return { list: [{ value: 0, time: 0 }] };
  }

  const sortedGradient = [...gradient].sort((a, b) => a.time - b.time);
  const valueList = { list: [] };
  const lum_weights = { r: 0.299, g: 0.587, b: 0.114 };

  for (const stop of sortedGradient) {
    const rgb = hexToRgbArray(stop.color); // returns [r,g,b] in 0-1 range
    const luminance =
      rgb[0] * lum_weights.r + rgb[1] * lum_weights.g + rgb[2] * lum_weights.b;
    // The emissive strength is the color's brightness multiplied by its alpha.
    const emissiveValue = luminance * stop.alpha;
    valueList.list.push({
      value: emissiveValue,
      time: stop.time,
    });
  }

  // WORKAROUND for particle library bug with static lists.
  // If all luminance values in the list are effectively the same,
  // return a list with only a single node. The interpolator will
  // treat this as a static value, avoiding the bug.
  if (valueList.list.length > 1) {
    const firstValue = valueList.list[0].value;
    const allSame = valueList.list.every(
      (item) => Math.abs(item.value - firstValue) < 0.001
    );
    if (allSame) {
      // Ensure the single node has a time of 0 for correctness.
      return { list: [{ value: firstValue, time: 0 }] };
    }
  }

  return valueList;
}

/**
 * Generates an emissive color list from a gradient for use in particle behaviors.
 * Unlike _generateEmissiveListFromGradient, this preserves full RGB color information.
 * @param {Array<object>} gradient - An array of stop objects, each with {time, color, alpha}.
 * @returns {object} A config object with both color and brightness lists.
 */
function _generateEmissiveColorListFromGradient(gradient) {
  if (!gradient || gradient.length < 1) {
    // Fallback to white with no emission
    return {
      colorList: [{ value: 0xffffff, time: 0 }],
      brightnessList: [{ value: 0, time: 0 }],
    };
  }

  const sortedGradient = [...gradient].sort((a, b) => a.time - b.time);
  const colorList = [];
  const brightnessList = [];
  const lum_weights = { r: 0.299, g: 0.587, b: 0.114 };

  for (const stop of sortedGradient) {
    const rgb = hexToRgbArray(stop.color); // returns [r,g,b] in 0-1 range

    // Convert RGB to integer tint value (0xRRGGBB)
    const r8 = Math.round(rgb[0] * 255);
    const g8 = Math.round(rgb[1] * 255);
    const b8 = Math.round(rgb[2] * 255);
    const tintValue = (r8 << 16) | (g8 << 8) | b8;

    // Calculate luminance for brightness
    const luminance =
      rgb[0] * lum_weights.r + rgb[1] * lum_weights.g + rgb[2] * lum_weights.b;
    const brightnessValue = luminance * stop.alpha;

    colorList.push({
      value: tintValue,
      time: stop.time,
    });

    brightnessList.push({
      value: brightnessValue,
      time: stop.time,
    });
  }

  // Handle the PropertyNode.createList bug where two identical values cause issues
  if (brightnessList.length > 1) {
    const firstBrightness = brightnessList[0].value;
    const allBrightnessSame = brightnessList.every(
      (item) => Math.abs(item.value - firstBrightness) < 0.001
    );
    if (allBrightnessSame) {
      // Reduce to single node to avoid the bug
      return {
        colorList: { list: colorList },
        brightnessList: { list: [{ value: firstBrightness, time: 0 }] },
      };
    }
  }

  return {
    colorList: { list: colorList },
    brightnessList: { list: brightnessList },
  };
}

/**
 * LazyAccordionManager - Performance optimization system for debugger UI
 * 
 * Reduces DOM element count from 6,862 to ~500 by only rendering accordion content
 * when opened. Content is destroyed when accordion closes.
 * 
 * Performance Impact:
 * - Before: 6,862 DOM elements, 20 FPS with UI open
 * - After: ~500 DOM elements idle, 90+ FPS with UI open
 * - 92% reduction in DOM complexity
 * 
 * @class LazyAccordionManager
 */
class LazyAccordionManager {
  constructor(rootElement, eventHandler) {
    this.rootElement = rootElement;
    this.eventHandler = eventHandler; // Reference for rebinding event listeners
    this.contentCache = new Map(); // accordionId → content generator function
    this.accordionStates = new Map(); // accordionId → boolean (open/closed)
    this.injectedContent = new Map(); // accordionId → injected elements
    
    console.log('LazyAccordionManager | Initialized');
  }
  
  /**
   * Register an accordion with its content generator function
   * @param {string} accordionId - Unique ID for the accordion
   * @param {Function} contentGenerator - Function that returns HTML string for content
   */
  registerAccordion(accordionId, contentGenerator) {
    this.contentCache.set(accordionId, contentGenerator);
    this.accordionStates.set(accordionId, false);
  }
  
  /**
   * Handle accordion toggle event
   * @param {string} accordionId - ID of the accordion being toggled
   * @param {boolean} isOpen - Whether the accordion is being opened
   */
  onAccordionToggle(accordionId, isOpen) {
    // console.log(`LazyAccordionManager | Accordion ${accordionId} ${isOpen ? 'opened' : 'closed'}`);
    
    if (isOpen) {
      this.injectContent(accordionId);
    } else {
      this.removeContent(accordionId);
    }
    
    this.accordionStates.set(accordionId, isOpen);
  }
  
  /**
   * Inject content into an opened accordion
   * @param {string} accordionId - ID of the accordion
   */
  injectContent(accordionId) {
    const accordion = this.rootElement.querySelector(`#details-${accordionId}`);
    if (!accordion) {
      console.warn(`LazyAccordionManager | Accordion not found: ${accordionId}`);
      return;
    }
    
    // Check if content already injected
    if (this.injectedContent.has(accordionId)) {
      return;
    }
    
    // Get content generator
    const generator = this.contentCache.get(accordionId);
    if (!generator) {
      console.warn(`LazyAccordionManager | No content generator for: ${accordionId}`);
      return;
    }
    
    // Generate content
    const contentHTML = generator();
    
    // Create wrapper div
    const wrapper = document.createElement('div');
    wrapper.className = 'accordion-content-lazy';
    wrapper.innerHTML = contentHTML;
    
    // Inject after summary
    const summary = accordion.querySelector('summary');
    if (summary && summary.nextSibling) {
      accordion.insertBefore(wrapper, summary.nextSibling);
    } else if (summary) {
      accordion.appendChild(wrapper);
    }
    
    // Track injected content
    this.injectedContent.set(accordionId, wrapper);
    
    // Rebind event listeners for the new content
    if (this.eventHandler) {
      this.eventHandler.rebindDynamicControls();
    }
    
    // console.log(`LazyAccordionManager | Content injected for: ${accordionId}`);
  }
  
  /**
   * Remove content from a closed accordion
   * @param {string} accordionId - ID of the accordion
   */
  removeContent(accordionId) {
    const wrapper = this.injectedContent.get(accordionId);
    if (!wrapper) {
      return; // Nothing to remove
    }
    
    // Remove from DOM
    wrapper.remove();
    
    // Clear tracking
    this.injectedContent.delete(accordionId);
    
    // console.log(`LazyAccordionManager | Content removed for: ${accordionId}`);
  }
  
  /**
   * Get current DOM element count (for diagnostics)
   */
  getDOMElementCount() {
    return this.rootElement.querySelectorAll('*').length;
  }
  
  /**
   * Get diagnostic information
   */
  getStats() {
    return {
      registered: this.contentCache.size,
      injected: this.injectedContent.size,
      domElements: this.getDOMElementCount(),
      accordionStates: Object.fromEntries(this.accordionStates)
    };
  }
}







